"""Function-level (AST, docstrings ignored) comparison of the three changed
code blocks v3 -> v4, and the value comparison of the specification's carried
cell blocks v3 -> v4."""
import ast, yaml, difflib
def funcs(p):
    t = ast.parse(open(p).read()); out = {}
    for n in t.body:
        if isinstance(n, (ast.FunctionDef, ast.ClassDef)):
            body = n.body
            if body and isinstance(body[0], ast.Expr) and isinstance(getattr(body[0], "value", None), ast.Constant): body = body[1:]
            out[n.name] = ast.dump(ast.Module(body=body, type_ignores=[])) + (ast.dump(n.args) if isinstance(n, ast.FunctionDef) else "")
        if isinstance(n, ast.Assign):
            for tg in n.targets:
                if isinstance(tg, ast.Name): out["CONST " + tg.id] = ast.dump(n.value)
    return out
for f in ["families.py", "stage1_gate.py", "exact_content.py"]:
    a = funcs("ext_v3/" + f); b = funcs("ext_v4/" + f)
    print("==", f)
    print(" unchanged (code; docstrings ignored):", [k for k in a if k in b and a[k] == b[k]])
    print(" changed:", [k for k in a if k in b and a[k] != b[k]])
    print(" removed:", [k for k in a if k not in b]); print(" added:", [k for k in b if k not in a])
s3 = yaml.safe_load(open("v3/EXP-BINSTD-c9c8a2__specification.yaml"))["experiment"]
s4 = yaml.safe_load(open("v4_head/EXP-BINSTD-811a2e__specification.yaml"))["experiment"]
c3, c4 = s3["cells"], s4["cells"]
print("== specification cells v3 -> v4")
print(" ladder identical:", c3["ladder"] == c4["ladder"], "| fixed_alphabet identical:", c3["fixed_alphabet"] == c4["fixed_alphabet"])
for k in ["composite_control", "ordinary_control", "calibration_cell", "exact_grid_control"]:
    a = {kk: vv for kk, vv in c3[k].items() if kk != "role"}; b = {kk: vv for kk, vv in c4[k].items() if kk != "role"}
    print(" %s non-role fields identical: %s" % (k, a == b))
    if c3[k].get("role") != c4[k].get("role"): print("   role text v3:", c3[k].get("role")); print("   role text v4:", c4[k].get("role"))
print(" generic control ids and objects identical:", [(g["id"], g["object"]) for g in c3["generic_controls"]] == [(g["id"], g["object"]) for g in c4["generic_controls"]])
for g3, g4 in zip(c3["generic_controls"], c4["generic_controls"]):
    if g3 != g4: print("   generic control text v3:", g3); print("   generic control text v4:", g4)
print(" declared_filter_families v4:", s4["definitions"]["declared_filter_families"])

