# D-CARRY-B: extract carried blocks from v3 and v4 audit sheets with the same script; diff value by value.
import yaml, json, sys
def load(p): return yaml.safe_load(open(p, encoding='utf-8'))['proof_search_map_audit']
v3 = load('v3/TASK-20260929-749b50__proof-search-map-audit.yaml')
v4 = load('v4_head/TASK-20261002-f48089__proof-search-map-audit.yaml')
def flat(x, pre=''):
    out = {}
    if isinstance(x, dict):
        for k, v in x.items():
            out.update(flat(v, f'{pre}.{k}' if pre else str(k)))
    elif isinstance(x, list):
        for i, v in enumerate(x):
            out.update(flat(v, f'{pre}[{i}]'))
    else:
        out[pre] = x
    return out
CARRIED = ['stage_0.pinned_inputs','stage_0.budget_quantity_statement','stage_0.capacity_certificate','stage_0.ideal_tree_table',
 'stage_0.design_corrections','stage_0.floors','stage_0.heur_b2_thresholds','stage_0.koblitz_orders','stage_0.ladder_choice',
 'stage_0.sample_table','stage_0.closed_form_needs','stage_0.null_scale','stage_0.resolving_floor','stage_0.bootstrap_removal',
 'stage_0.cost_table','stage_0.design_findings','exact_quotient_audit_table']
def get(d, path):
    for k in path.split('.'):
        d = d.get(k) if isinstance(d, dict) else None
    return d
res = {}
for blk in CARRIED:
    a = flat(get(v3, blk), blk); b = flat(get(v4, blk), blk)
    keys = sorted(set(a) | set(b))
    diffs = []
    for k in keys:
        if a.get(k, '<absent>') != b.get(k, '<absent>'):
            diffs.append(dict(path=k, v3=a.get(k, '<absent>'), v4=b.get(k, '<absent>')))
    res[blk] = dict(n_leaves_v3=len(a), n_leaves_v4=len(b), n_diff=len(diffs), diffs=diffs)
json.dump(res, open('dcarry_out.json', 'w'), indent=1, default=str)
for blk, r in res.items():
    print(f"{blk}: leaves v3={r['n_leaves_v3']} v4={r['n_leaves_v4']} differing={r['n_diff']}")

