compare_audit.py.text:
"""Compare independent exhaustive purities with CODE-AUDIT's frozen C-4 rows
(carried table): exact at the table's 6 printed decimals on exhaustive rows,
within 3 standard errors (non-degenerate [0, 3/N] interval at 0) on sampled rows."""
import json, math
mine = {}
for p in ["out/indep_K13.json", "out/indep_K19_O19.json", "out/indep_K23.json"]:
    for r in json.load(open(p))["rows"]:
        mine[(r["cell"], r["role"], r["M"])] = r
N_OF = {"CELL-K13": 13, "CELL-K19": 19, "CELL-K23": 23, "CELL-O19": 19, "CELL-K41": 41}
def role_of(cell, arm, off, M):
    n = N_OF[cell]; r = M.bit_length() - 1
    offs = (0, (n - r) // 2, n - r)
    pre = "ORD-" if cell == "CELL-O19" else ""
    if arm.startswith("ORD-"): arm = arm[4:]
    if arm in ("F2", "F3"):
        o = int(off); idx = offs.index(o)
        return pre + arm + "@" + ("0", "mid", "end")[idx]
    if arm in ("F5xF2", "F5xF3"): return arm + "@0"
    return arm
ex = sa = bad = 0; notes = []
for line in open("emb_c4_audit_out.txt"):
    d = json.loads(line)
    if "arm" not in d: continue
    k = (d["cell"], role_of(d["cell"], d["arm"], d["offset"], d["M"]), d["M"])
    if k not in mine: continue
    m = mine[k]
    for q in ("purity_2", "purity_4"):
        pv = d[q]
        if pv is None and m[q] is None: continue
        if d["mode"] == "exhaustive":
            ex += 1
            if round(m[q], 6) != pv: bad += 1; notes.append(("EXH", k, q, m[q], pv))
        else:
            sa += 1
            se = d["se_2" if q == "purity_2" else "se_4"] or 0.0
            tol = 3 * se if se > 0 else 3.0 / d["points"]
            if abs(m[q] - pv) > tol: bad += 1; notes.append(("SAMP", k, q, m[q], pv, se))
            elif q == "purity_2" and k[1] == "F1": notes.append(("SAMP-ok", k, q, round(m[q], 8), pv, se, round((pv - m[q]) / se, 2)))
print("exhaustive purity comparisons:", ex, "sampled comparisons:", sa, "outside tolerance:", bad)
for n in notes: print(n)

