"""Compare the independent enumeration rows with the producer's frozen C-4
CODE-DEGEN rows embedded in the audit sheet (exact on exhaustive rows)."""
import json, sys
def load_prod(paths):
    rows = {}
    metas = {}
    for p in paths:
        for line in open(p):
            line = line.strip()
            if not line: continue
            d = json.loads(line)
            if "cell_meta" in d: metas[d["cell_meta"]["cell"]] = d["cell_meta"]; continue
            if "not_regular" in d: continue
            rows[(d["cell"], d["role"], d["M"])] = d
    return rows, metas
prod, pmeta = load_prod(["emb_c4_degen_small_out.txt", "emb_c4_degen_k23_out.txt", "emb_c4_degen_k41_out.txt"])
mine_rows, mine_meta = {}, {}
for p in sys.argv[1:]:
    d = json.load(open(p))
    for m in d["metas"]: mine_meta[m["cell"]] = m
    for r in d["rows"]: mine_rows[(r["cell"], r["role"], r["M"])] = r
keys = ["image_size", "smallest_class", "largest_class", "c_2", "c_4", "class", "points"]
fkeys = ["purity_2", "purity_4", "c_q_fraction"]
n_cmp = n_bad = 0
bad = []
for k, r in sorted(mine_rows.items()):
    p = prod.get(k)
    if p is None:
        bad.append(("MISSING_IN_PRODUCER", k)); n_bad += 1; continue
    n_cmp += 1
    diffs = {}
    for kk in keys:
        if r.get(kk) != p.get(kk): diffs[kk] = (r.get(kk), p.get(kk))
    for kk in fkeys:
        a, b = r.get(kk), p.get(kk)
        if (a is None) != (b is None) or (a is not None and abs(a - b) > 1e-12): diffs[kk] = (a, b)
    if diffs:
        n_bad += 1; bad.append((k, diffs))
for c, m in mine_meta.items():
    pm = pmeta.get(c, {})
    print("META", c, "mine poly", m["field_poly"], "w", m["normal_element"], "| producer poly", pm.get("field_poly"), "w", pm.get("normal_element"), "points", pm.get("points"), "vs", m["affine_points"])
print("rows compared:", n_cmp, "rows differing:", n_bad)
for b in bad: print("DIFF", b)
cells_mine = set(k[0] for k in mine_rows)
missing = [k for k in prod if k[0] in cells_mine and k not in mine_rows]
print("producer rows on my cells not in mine:", missing)

