comparison_script.text:
"""Compare every re-run relayed computation with the digest the audit sheet
records for it; for CODE-DEGEN (C-4) compare row lines with the wall-clock
'seconds' field of cell_meta removed (as IR-24 prescribes), against the texts
embedded in the sheet. Summarise the guard logs."""
import yaml, json, hashlib, os, re
S = os.path.dirname(os.path.abspath(__file__))
A = yaml.safe_load(open(os.path.join(S, "v4_head/TASK-20261002-f48089__proof-search-map-audit.yaml")))["proof_search_map_audit"]
dc = A["design_computations"]
exp = {}
for j in dc["round_2"]["jobs"]:
    m = re.search(r"> (\S+)", j["command"])
    if m: exp[m.group(1).rstrip(",")] = (j["item"], j["output_sha256"], j["command"], j.get("real_s"))
exp["c7.out"] = ("C-7", dc["C-7"]["output_sha256"].split()[0], "dryrun.py namegrid", None)
exp["c8.out"] = ("C-8", dc["C-8"]["output_sha256"].split()[0], "dryrun.py dry", None)
exp["ff_analytic.json"] = ("C-5", dc["C-5-round-1"]["analytic"]["output_sha256"].split()[0], "falsefire.py analytic", None)
exp["ff_nearexact.json"] = ("C-5", dc["C-5-round-1"]["nearexact"]["output_sha256"].split()[0], "falsefire.py nearexact", None)
exp["ff_table2.json"] = ("C-5", dc["C-5-combine-round-3"]["output_sha256"].split()[0], "falsefire.py combine (round 3 file list)", None)
exp["c3.out"] = ("C-3", "716d2e8becafd4e95f74d363e100f318d83affb79740460a9a4b01428934ee06", "stage0.py", None)
exp.pop("ff_table.json", None)   # first combine ran under the superseded CODE-FF bytes; not reproducible from committed code
joblog = {}
if os.path.exists(os.path.join(S, "out/joblog.txt")):
    for line in open(os.path.join(S, "out/joblog.txt")):
        name = line.split()[0]; rc = re.search(r"rc=(\d+)", line).group(1); ws = re.search(r"wall_s=([\d.]+)", line).group(1)
        joblog[name] = (int(rc), float(ws))
def strip_seconds(text):
    out = []
    for line in text.splitlines():
        d = json.loads(line)
        if "cell_meta" in d: d["cell_meta"].pop("seconds", None)
        out.append(json.dumps(d, sort_keys=True))
    return out
emb = {"c4_audit.out": "emb_c4_audit_out.txt", "c4_degen_small.out": "emb_c4_degen_small_out.txt", "c4_degen_k23.out": "emb_c4_degen_k23_out.txt", "c4_degen_k41.out": "emb_c4_degen_k41_out.txt"}
rows = []
for name, (item, sha, cmd, real) in sorted(exp.items()):
    p = os.path.join(S, "out", name)
    r = {"output": name, "item": item, "command": cmd, "recorded_sha256": sha, "producer_real_s": real}
    if name in joblog: r["rc"], r["my_wall_s"] = joblog[name]
    if not os.path.exists(p) or os.path.getsize(p) == 0:
        r["status"] = "NOT AVAILABLE (not run or not finished)"
    else:
        b = open(p, "rb").read(); h = hashlib.sha256(b).hexdigest()
        r["my_sha256"] = h; r["bytes"] = len(b)
        if h == sha: r["status"] = "byte-identical"
        elif name in emb:
            mine = strip_seconds(b.decode()); theirs = strip_seconds(open(os.path.join(S, emb[name])).read())
            r["status"] = ("row lines identical with the wall-clock seconds field removed (%d lines); bytes differ only there" % len(mine)
                           if mine == theirs else "DIFFERS beyond the seconds field")
        else:
            r["status"] = "DIFFERS"
    g = os.path.join(S, "glog", name + ".json")
    if os.path.exists(g):
        d = json.load(open(g))
        r["guard_mode"] = d.get("mode"); r["guard_violation"] = "VIOLATION" in d
        r["groups_constructed"] = sorted(k for k in d.get("seen", {}) if not k.startswith("PairStream") and not k.startswith("mode"))
        r["pair_streams"] = sum(v for k, v in d.get("seen", {}).items() if k.startswith("PairStream"))
    rows.append(r)
print(json.dumps(rows, indent=1, sort_keys=True))

