role_pairs_check.py.text:
"""Check, on the frozen C-4 CODE-DEGEN rows, that each role maps to the
numeric offset name floor((n - r) / 2) (@mid) or n - r (@end) on every cell."""
import json
N = {"CELL-K13": 13, "CELL-K19": 19, "CELL-K23": 23, "CELL-O19": 19, "CELL-K41": 41}
bad = 0; n_ok = 0
for f in ["emb_c4_degen_small_out.txt", "emb_c4_degen_k23_out.txt", "emb_c4_degen_k41_out.txt"]:
    for line in open(f):
        d = json.loads(line)
        if "role" not in d: continue
        n = N[d["cell"]]; r = d["M"].bit_length() - 1; offs = (0, (n - r) // 2, n - r)
        role = d["role"]; num = d["numeric_name"]; base = role.replace("ORD-", "")
        if "@" in base and base.split("@")[0] in ("F2", "F3"):
            fam_, pos = base.split("@"); o = offs[{"0": 0, "mid": 1, "end": 2}[pos]]
            want = ("ORD-" if role.startswith("ORD-") else "") + fam_ + "@" + str(o)
        else:
            want = role
        if want != num: bad += 1; print("MISMATCH", d["cell"], d["M"], role, num, want)
        else: n_ok += 1
print("role/numeric pairs consistent:", n_ok, "mismatches:", bad)

trunc_check.py.text:
"""Find YAML text after ' #' on non-comment lines that does NOT survive into
any parsed scalar (i.e. was swallowed as a comment) - RV-11 truncation check."""
import yaml, sys, re
def scalars(x, out):
    if isinstance(x, dict):
        for k, v in x.items(): scalars(k, out); scalars(v, out)
    elif isinstance(x, list):
        for v in x: scalars(v, out)
    elif isinstance(x, str): out.append(x)
for p in sys.argv[1:]:
    raw = open(p, encoding="utf-8").read()
    d = yaml.safe_load(raw)
    ss = []; scalars(d, ss)
    blob = "\n".join(ss)
    blob_ns = re.sub(r"\s+", " ", blob)
    hits = []
    for i, line in enumerate(raw.split("\n"), 1):
        st = line.lstrip()
        if not st or st.startswith("#"): continue
        j = line.find(" #")
        while j >= 0:
            tail = line[j + 2:].strip()
            frag = re.sub(r"\s+", " ", tail)[:40]
            if frag and frag not in blob_ns:
                hits.append((i, line.strip()[:160]))
                break
            j = line.find(" #", j + 1)
    print(p, "lines with swallowed ' #' text:", len(hits))
    for h in hits: print("  ", h)
